// NewListEventLogPayload builds a otel service listEventLog endpoint payload.
func NewListEventLogPayload(body *ListEventLogRequestBody, sessionToken *string) *otel.ListEventLogPayload {
	v := &otel.ListEventLogPayload{
		From:   *body.From,
		To:     *body.To,
		Search: body.Search,
		Cursor: body.Cursor,
	}
	if body.Limit != nil {
		v.Limit = *body.Limit
	}
	if body.Kinds != nil {
		v.Kinds = make([]string, len(body.Kinds))
		for i, val := range body.Kinds {
			v.Kinds[i] = val
		}
	}
	if body.Sources != nil {
		v.Sources = make([]string, len(body.Sources))
		for i, val := range body.Sources {
			v.Sources[i] = val
		}
	}
	if body.Names != nil {
		v.Names = make([]string, len(body.Names))
		for i, val := range body.Names {
			v.Names[i] = val
		}
	}
	if body.Limit == nil {
		v.Limit = 50
	}
	v.SessionToken = sessionToken

	return v
}

